// Normaliza el payload del form Meta
// Entrada esperada: { telefono, nombre, email, programa, lead_id, form_id, ... }
// Defaults: país AR, programa Boarding School

const body = $input.first().json.body || $input.first().json || {};

let telefono = (body.telefono || body.phone || body.phone_number || body.full_phone_number || '').toString().trim();
// Limpiar caracteres no-numéricos excepto el +
telefono = telefono.replace(/[^0-9+]/g, '');
// Normalizar a E.164 con default AR (+549)
if (telefono) {
  if (telefono.startsWith('+')) {
    // Ya está en E.164
  } else if (telefono.startsWith('549')) {
    telefono = '+' + telefono;
  } else if (telefono.startsWith('54')) {
    telefono = '+' + telefono;
  } else {
    // Asumir número local AR — agregar prefijo +549, quitar 0 inicial si lo tiene
    telefono = '+549' + telefono.replace(/^0/, '');
  }
}

const telefonoSinPlus = telefono.replace('+', '');
const nombre = (body.nombre || body.first_name || body.full_name || body.name || '').toString().trim().split(' ')[0] || 'Lead';
const nombreCompleto = (body.full_name || body.name || body.nombre || '').toString().trim();
const apellido = nombreCompleto.split(' ').slice(1).join(' ') || '';
const email = (body.email || '').toString().trim().toLowerCase();
const programa = (body.programa || body.program || body.programa_interes || 'Boarding School').toString().trim();
const metaLeadId = (body.lead_id || body.leadgen_id || '').toString();
const metaFormId = (body.form_id || '').toString();
const metaCampaignId = (body.campaign_id || '').toString();

if (!telefono || telefonoSinPlus.length < 8) {
  throw new Error(`Teléfono inválido o ausente en el payload: "${telefono}"`);
}

return [{
  json: {
    telefono,
    telefono_sin_plus: telefonoSinPlus,
    nombre,
    apellido,
    email,
    programa,
    origen: 'Form Meta',
    meta_lead_id: metaLeadId,
    meta_form_id: metaFormId,
    meta_campaign_id: metaCampaignId,
    received_at: new Date().toISOString(),
  }
}];

